package org.bukkit.event.player;
import org.bukkit.entity.Player; import org.bukkit.inventory.meta.BookMeta; import org.bukkit.event.Cancellable; import org.bukkit.event.HandlerList;
public final class PlayerEditBookEvent extends PlayerEvent implements Cancellable { private final int slot; private boolean cancelled; private static final HandlerList HANDLERS=new HandlerList(); public PlayerEditBookEvent(Player p,int slot){super(p);this.slot=slot;} public int getSlot(){return slot;} public BookMeta getPreviousBookMeta(){return null;} public BookMeta getNewBookMeta(){return null;} public boolean isSigning(){return false;} public boolean isCancelled(){return cancelled;} public void setCancelled(boolean v){cancelled=v;} public HandlerList getHandlers(){return HANDLERS;} public static HandlerList getHandlerList(){return HANDLERS;} }
